    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Going to for Evidence-Based Predictions';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Going to for Evidence-Based Predictions','Present evidence can make a future result seem likely.','Objective: Use going to for a prediction based on visible evidence.
Content: Use be going to when what you can see or know now points to a future event.
Examples:
- Look at the clouds. It is going to rain.
- The child is tired, so she is going to sleep.
Common errors and corrections:
- Do not use a past form after going to.
- Use the subject''s correct be form.
Guided practice: Identify the evidence first, then choose going to for the likely result.
Summary: Going to can predict a result when present evidence supports it.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
