    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Will for Decisions, Offers, and Promises','Will often responds to a new situation rather than a plan made earlier.','Objective: Use will for a decision made at speaking time, an offer, or a promise.
Content: Use will plus the base verb for quick decisions, offers, and promises.
Examples:
- The phone is ringing. I will answer it.
- I will help you with that bag.
Common errors and corrections:
- Do not add to after will.
- Do not use will to describe every prior plan.
Guided practice: Look for a new situation, an offer, or a promise made now.
Summary: Will expresses a spontaneous decision, offer, or promise.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
