    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Choosing Will or Going to';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Choosing Will or Going to','The context tells us whether the idea is a prior plan, evidence-based prediction, or decision now.','Objective: Choose will or going to from a clear everyday context.
Content: Use going to for earlier plans and present evidence; use will for offers, promises, and decisions made now.
Examples:
- We planned it, so we are going to meet.
- The phone rings, so I will answer it.
Common errors and corrections:
- Do not choose only by the time word.
- Check whether the plan existed before the conversation.
Guided practice: Label each context plan, evidence, or decision now before choosing the form.
Summary: Going to and will have different uses in clear contexts.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
